// Tells you when the MEP moved 2% or more since the last notice, or crossed a limit you set.
const UMBRAL = 0.02;
const AVISAR_SI_SUPERA = null;   // por ejemplo 1700
const AVISAR_SI_BAJA_DE = null;  // por ejemplo 1400

const all = $input.all().map(i => i.json);
const mep = all.find(d => d.casa === 'bolsa')?.venta;
const blue = all.find(d => d.casa === 'blue')?.venta;
if (!mep) return [];
const fmt = n => '$ ' + Math.round(n).toLocaleString('es-AR');
const s = $getWorkflowStaticData('global');
const out = [];
if (!s.base) {
  s.base = mep;  // first run: just remember where it starts
} else {
  const cambio = (mep - s.base) / s.base;
  if (Math.abs(cambio) >= UMBRAL) {
    const pct = (Math.abs(cambio) * 100).toFixed(1).replace('.', ',');
    out.push(`El MEP ${cambio > 0 ? 'subió' : 'bajó'} ${pct}% desde el último aviso (${fmt(s.base)}).`);
    s.base = mep;
  }
}
for (const [lim, arriba] of [[AVISAR_SI_SUPERA, true], [AVISAR_SI_BAJA_DE, false]]) {
  if (!lim) continue;
  const key = `${arriba ? 'sobre' : 'bajo'}_${lim}`;
  const cruzado = arriba ? mep >= lim : mep <= lim;
  if (cruzado && !s[key]) out.push(`${arriba ? 'Pasó' : 'Bajó de'} ${fmt(lim)}.`);
  s[key] = cruzado;
}
if (!out.length) return [];
return [{ json: {
  title: `Dólar MEP ${fmt(mep)}`, message: out.join(' ') + (blue ? ` Blue ${fmt(blue)}.` : ''),
  tag: 'dollar', click: 'https://mac-server.tailnet-ejemplo.ts.net:3013/evolucion?ver=usd',
} }];
